import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.when;

/**
 * Unit tests for JacksonAnnotationIntrospector.findNameForSerialization
 */
public class JacksonAnnotationIntrospector_findNameForSerialization_TriageGen2Test {

    private JacksonAnnotationIntrospector introspector;
    private Annotated annotatedMock;

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
        annotatedMock = Mockito.mock(Annotated.class);
    }

    /**
     * Helper to mock the internal _findAnnotation behavior via the Annotated interface 
     * if the introspector uses it, or by mocking the annotation lookup.
     * Since _findAnnotation is protected and uses annotation lookup, 
     * we mock the annotation presence on the 'a' object.
     */
    private <T extends Annotation> void mockAnnotation(Class<T> annotationClass, T annotationInstance) {
        // In Jackson's actual implementation, _findAnnotation calls a.getAnnotation(Class)
        when(annotatedMock.getAnnotation(annotationClass)).thenReturn(annotationInstance);
    }

    @Test
    public void testFindName_WithJsonGetter() {
        JsonGetter getter = Mockito.mock(JsonGetter.class);
        when(getter.value()).thenReturn("getterName");
        mockAnnotation(JsonGetter.class, getter);

        PropertyName result = introspector.findNameForSerialization(annotatedMock);

        assertEquals("getterName", result.toString());
    }

    @Test
    public void testFindName_WithJsonProperty() {
        // Ensure JsonGetter returns null to trigger the else block
        when(annotatedMock.getAnnotation(JsonGetter.class)).thenReturn(null);

        JsonProperty property = Mockito.mock(JsonProperty.class);
        when(property.value()).thenReturn("propertyValue");
        mockAnnotation(JsonProperty.class, property);

        PropertyName result = introspector.findNameForSerialization(annotatedMock);

        assertEquals("propertyValue", result.toString());
    }

    @Test
    public void testFindName_WithJsonSerialize() {
        when(annotatedMock.getAnnotation(JsonGetter.class)).thenReturn(null);
        when(annotatedMock.getAnnotation(JsonProperty.class)).thenReturn(null);

        // Mock _hasAnnotation logic via getAnnotation
        when(annotatedMock.getAnnotation(JsonSerialize.class)).thenReturn(Mockito.mock(JsonSerialize.class));

        PropertyName result = introspector.findNameForSerialization(annotatedMock);

        assertEquals("", result.toString());
    }

    @Test
    public void testFindName_WithJsonView() {
        when(annotatedMock.getAnnotation(JsonGetter.class)).thenReturn(null);
        when(annotatedMock.getAnnotation(JsonProperty.class)).thenReturn(null);

        when(annotatedMock.getAnnotation(JsonSerialize.class)).thenReturn(null);
        when(annotatedMock.getAnnotation(JsonView.class)).thenReturn(Mockito.mock(JsonView.class));

        PropertyName result = introspector.findNameForSerialization(annotatedMock);

        assertEquals("", result.toString());
    }

    @Test
    public void testFindName_WithJsonRawValue() {
        when(annotatedMock.getAnnotation(JsonGetter.class)).thenReturn(null);
        when(annotatedMock.getAnnotation(JsonProperty.class)).thenReturn(null);

        when(annotatedMock.getAnnotation(JsonSerialize.class)).thenReturn(null);
        when(annotatedMock.getAnnotation(JsonView.class)).thenReturn(null);
        when(annotatedMock.getAnnotation(JsonRawValue.class)).thenReturn(Mockito.mock(JsonRawValue.class));

        PropertyName result = introspector.findNameForSerialization(annotatedMock);

        assertEquals("", result.toString());
    }

    @Test
    public void testFindName_NoAnnotations() {
        when(annotatedMock.getAnnotation(JsonGetter.class)).thenReturn(null);
        when(annotatedMock.getAnnotation(JsonProperty.class)).thenReturn(null);
        when(annotatedMock.getAnnotation(JsonSerialize.class)).thenReturn(null);
        when(annotatedMock.getAnnotation(JsonView.class)).thenReturn(null);
        when(annotatedMock.getAnnotation(JsonRawValue.class)).thenReturn(null);

        PropertyName result = introspector.findNameForSerialization(annotatedMock);

        assertNull(result);
    }

    @Test
    public void testFindName_WithJsonGetterEmptyString() {
        JsonGetter getter = Mockito.mock(JsonGetter.class);
        when(getter.value()).thenReturn("");
        mockAnnotation(JsonGetter.class, getter);

        PropertyName result = introspector.findNameForSerialization(annotatedMock);

        assertEquals("", result.toString());
    }
}
